import * as T from './three.module.js';import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
export function batchScenery(scene,{exclude=[],buildings=[],register=()=>{}}={}){const excluded=new Set(exclude),targets=[];for(const o of scene.children)if(o.isMesh&&!o.isSkinnedMesh&&!o.isInstancedMesh&&!excluded.has(o)&&!o.userData.station&&!o.userData.animal&&o.material?.isMeshStandardMaterial&&o.geometry?.attributes.uv)targets.push(o);for(const b of buildings)if(b.g.visible)b.g.traverse(o=>{if(o.isMesh&&!o.isSkinnedMesh&&!o.isInstancedMesh&&o.geometry?.attributes.uv)targets.push(o);});scene.updateMatrixWorld(true);const buckets=new Map();for(const o of targets){const m=o.material;if(Array.isArray(m))continue;const station=o.userData.station,key=[m.type,m.color?.getHex(),m.roughness,m.metalness,m.opacity,m.transparent,m.side,m.map?.uuid,m.bumpMap?.uuid,m.bumpScale,m.emissive?.getHex(),m.emissiveIntensity,o.castShadow,station?.kind,station?.x,station?.z].join('|');if(!buckets.has(key))buckets.set(key,{material:m,station,geos:[],objects:[],cast:o.castShadow});const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);const b=buckets.get(key);b.geos.push(g);b.objects.push(o);}
 let saved=0;for(const b of buckets.values()){if(b.objects.length<2){for(const g of b.geos)g.dispose();continue;}const geometry=mergeGeometries(b.geos);for(const g of b.geos)g.dispose();if(!geometry)continue;const mesh=new T.Mesh(geometry,b.material);mesh.name='Batched static farm scenery';mesh.castShadow=b.cast;mesh.receiveShadow=true;scene.add(mesh);if(b.station)register(mesh,b.station);for(const o of b.objects){o.visible=false;o.removeFromParent();}saved+=b.objects.length-1;}return saved;}
